// cc -O2 gen.c -lm -o gen && ./gen 6000000 > vec.txt
// each line: the bits of a, b, c and of fmaf(a, b, c), from six kinds of triple
#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static uint64_t z = 88172645463325252ull;
static uint32_t rnd(void) { z ^= z << 13; z ^= z >> 7; z ^= z << 17; return (uint32_t)(z >> 32); }
static float fb(uint32_t u) { float f; memcpy(&f, &u, 4); return f; }
static uint32_t bf(float f) { uint32_t u; memcpy(&u, &f, 4); return u; }

int main(int argc, char** argv) {
  long n = atol(argv[1]);
  for (long i = 0; i < n; i++) {
    uint32_t a = rnd(), b = rnd(), c = rnd();
    int k = i % 6;                               // 0: any bits
    if (k == 1) {                                // moderate exponents
      a = (a & 0x807FFFFF) | ((100 + rnd() % 55) << 23);
      b = (b & 0x807FFFFF) | ((100 + rnd() % 55) << 23);
      c = (c & 0x807FFFFF) | ((80 + rnd() % 95) << 23);
    } else if (k == 2) {                         // c within 3 ulps of -(a * b)
      a = (a & 0x807FFFFF) | ((110 + rnd() % 35) << 23);
      b = (b & 0x807FFFFF) | ((110 + rnd() % 35) << 23);
      c = bf(-(fb(a) * fb(b))) + (int32_t)(rnd() % 7) - 3;
    } else if (k == 3) {                         // short mantissas
      a = (a & 0x80000000) | ((120 + rnd() % 15) << 23) | ((rnd() & 0xFFF) << 11);
      b = (b & 0x80000000) | ((120 + rnd() % 15) << 23) | ((rnd() & 0xFFF) << 11);
      c = (c & 0x80000000) | ((100 + rnd() % 40) << 23) | (rnd() & 0x7FFFFF);
    } else if (k >= 4) {                         // a * b just off a power of two, so
      uint32_t m = 1 + rnd() % 64;               // a double sum can land on a halfway
      uint32_t ea = 60 + rnd() % 100, eb = 60 + rnd() % 60;
      a = (rnd() & 0x80000000) | (ea << 23) | m;
      b = (rnd() & 0x80000000) | (eb << 23) | (k == 4 ? 0 : m);
      if (k == 4) b = bf(fb(b) * (1.0f - m * 0x1p-23f));
      int ec = (int)ea + (int)eb - 127 + 24 + (int)(rnd() % 3) - 1;
      if (ec < 1 || ec > 254) ec = 127;
      c = (rnd() & 0x80000000) | ((uint32_t)ec << 23) | (rnd() % 4 == 0 ? 0 : rnd() & 0x7FFFFF);
    }
    printf("%u %u %u %u\n", a, b, c, bf(fmaf(fb(a), fb(b), fb(c))));
  }
  return 0;
}
