import Base

# pure-Bend fma, from F32 add/sub/mul only: the exact product (Veltkamp
# split, Dekker), three TwoSums, and one halfway fix. Valid while 4097 * a,
# a * b and the product's error neither overflow nor underflow (no special
# values handled): a lower bound on a complete emulation's cost.

def emu.hi(+g: F32, +a: F32) -> F32:
  F32.sub(g, F32.sub(g, a))

def emu.err(+s: F32, +a: F32, +b: F32, +z: F32) -> F32:
  F32.add(F32.sub(a, F32.sub(s, z)), F32.sub(b, z))

def emu.two(+a: F32, +b: F32, +s: F32) -> F32:
  emu.err(s, a, b, F32.sub(s, a))

def emu.same(+x: F32, +y: F32) -> Bool:
  Bool.or(Bool.and(F32.is_gt(x, 0.0), F32.is_gt(y, 0.0)),
    Bool.and(F32.is_lt(x, 0.0), F32.is_lt(y, 0.0)))

def emu.fin(+zh: F32, +zl: F32, +vl: F32, +w: F32) -> F32:
  mid = F32.is_eq(F32.sub(w, zh), F32.add(zl, zl))
  Bool.pick(F32, Bool.and(mid, emu.same(vl, zl)), w, zh)

def emu.z(+vl: F32, +zh: F32, +zl: F32) -> F32:
  emu.fin(zh, zl, vl, F32.add(zh, F32.add(zl, zl)))

def emu.v(+sh: F32, +vh: F32, +vl: F32, +zh: F32) -> F32:
  emu.z(vl, zh, emu.two(sh, vh, zh))

def emu.s(+sh: F32, +sl: F32, +pl: F32, +vh: F32) -> F32:
  emu.v(sh, vh, emu.two(sl, pl, vh), F32.add(sh, vh))

def emu.q(+sh: F32, +pl: F32, +sl: F32) -> F32:
  emu.s(sh, sl, pl, F32.add(sl, pl))

def emu.p(+c: F32, +ph: F32, +pl: F32, +sh: F32) -> F32:
  emu.q(sh, pl, emu.two(ph, c, sh))

def emu.d(+c: F32, +ph: F32, +ah: F32, +al: F32, +bh: F32, +bl: F32) -> F32:
  emu.p(c, ph, F32.add(F32.add(F32.add(F32.sub(F32.mul(ah, bh), ph),
    F32.mul(ah, bl)), F32.mul(al, bh)), F32.mul(al, bl)), F32.add(ph, c))

def emu.split(+a: F32, +b: F32, +c: F32, +ah: F32, +bh: F32) -> F32:
