// signal.c
#include <signal.h>

static int signal_pipe[2] = { -1, -1 };

static void signal_note(int number) {
  unsigned char byte = (unsigned char)number;
  ssize_t n = write(signal_pipe[1], &byte, 1);
  (void)n;
}

static Term signal_next_more(Env e, IoWork* w) {
  unsigned char byte = 0;
  ssize_t n = read(signal_pipe[0], &byte, 1);
  if (n < 0 && (errno == EAGAIN || errno == EINTR)) {
    return io_wait_on(w, signal_pipe[0], POLLIN, 0, signal_next_more);
  }
  return (Term)(u32)byte;
}

Term signal_next_run(Env e, Term* f, IoWork* w) {
  if (signal_pipe[0] < 0) {
    if (pipe(signal_pipe) != 0) {
      return (Term)0;
    }
    fcntl(signal_pipe[0], F_SETFL, O_NONBLOCK);
    fcntl(signal_pipe[1], F_SETFL, O_NONBLOCK);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_note;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGTERM, &sa, NULL);
    sigaction(SIGINT, &sa, NULL);
  }
  return signal_next_more(e, w);
}

static void __attribute__((constructor)) signal_next_use(void) {
  io_eff(CID(Signal.next), signal_next_run, 0);
}
