// The same loop as tile.bend, handwritten: same layout, same order of every
// float operation, so it prints the same bits.
#include <stdint.h>
#include <stdio.h>
#include <string.h>

static float s[16384];

typedef struct { float c[4][4]; } A16;

static A16 tile(int k, uint32_t bo) {
  A16 r = {{{0}}};
  for (int t = 0; t < k; t++) {
    const float *a = s + 4 * t, *b = s + bo + 4 * t;
    for (int i = 0; i < 4; i++)
      for (int j = 0; j < 4; j++)
        r.c[i][j] = r.c[i][j] + a[i] * b[j];
  }
  return r;
}

static float sum16(A16 r) {
  float q[4];
  for (int i = 0; i < 4; i++) q[i] = (r.c[i][0] + r.c[i][1]) + (r.c[i][2] + r.c[i][3]);
  return (q[0] + q[1]) + (q[2] + q[3]);
}

int main(void) {
  for (uint32_t i = 0; i < 16384; i++) s[i] = (float)((i * 7u) % 1000u) / 1000.0f - 0.5f;
  float acc = 0, x = 0;
  uint32_t o = 0;
  for (int q = 0; q < 400000; q++) { acc = acc + x; x = sum16(tile(1024, 4096 + o)); o = (o + 4) % 4096; }
  acc = acc + x;
  uint32_t w; memcpy(&w, &acc, 4); printf("%u\n", w);
  return 0;
}
