```c
#define main bend_generated_main
#include RUNTIME_SOURCE
#undef main
#include <assert.h>
#include <stdatomic.h>

#define ITERATIONS 8192u

struct Run {
  u64* heap;
  _Atomic u32 start;
};

static void* publish(void* argument) {
  struct Run* run = argument;
  while (atomic_load_explicit(&run->start, memory_order_acquire) == 0) {}
  for (u32 i = 0; i < ITERATIONS; ++i) {
    ring_push(run->heap, 0, 0);
    a32_store_rel(ring_get(run->heap, 0),
      a32_load(ring_put(run->heap, 0)) - 1);
  }
  return NULL;
}

static void check_snapshots(u32 stride) {
  size_t bytes = (RING_OFF + (RING_LEN + 2) * LANES + CUBE_T) * sizeof(u64);
  struct Run run = { .heap = pool_mmap(bytes) };
  a32_store(a32_at(run.heap, H_ROOT_DONE), 0);
  a32_store(a32_at(run.heap, H_ERROR_CODE), 0);
  for (u32 i = 0; i < CUBE_T; ++i) {
    a32_store(ring_get(run.heap, i * stride), 0);
    a32_store(ring_put(run.heap, i * stride), 0);
  }
  ring_push(run.heap, 0, 0);
  ring_push(run.heap, stride, 0);
  pthread_t writer;
  assert(pthread_create(&writer, NULL, publish, &run) == 0);
  Term stack[STAK_LEN];
  Env environment = { run.heap, ALC[0] };
  atomic_store_explicit(&run.start, 1, memory_order_release);
  for (u32 i = 0; i < ITERATIONS; ++i) {
    assert(row_grow(environment, stack, 0, stride, 1, 0) == 0);
  }
  assert(pthread_join(writer, NULL) == 0);
  assert(a32_load(ring_put(run.heap, 0)) == ITERATIONS + 1);
  assert(a32_load(ring_get(run.heap, 0)) == ITERATIONS);
  assert(a32_load(a32_at(run.heap, H_ERROR_CODE)) == 0);
  u32* slot = (u32*)ring_slot(run.heap, 0, ITERATIONS);
  assert((a32_load_acq(slot + 1) >> 31) == ring_lap(ITERATIONS));
  assert(a32_load(slot) == 0);
  assert(munmap(run.heap, bytes) == 0);
  printf("stride=%u: %u real row_grow snapshots; ring counters and published lap preserved\n",
    stride, ITERATIONS);
}

int main(void) {
  check_snapshots(1);
  check_snapshots(CUBE_G);
  return 0;
}
```
