**Fix 2 (described, prototyped on v2.0.38 only): hold an owned row instead of taking it**

When an owned box is bound to a record pattern variable, and every use of that variable
is a lent argument to a non-tail call, the patch peeks the row instead of taking it. Its
words are rooted in a local root, and the box is dropped once when the variable dies. Any
use that needs the words owned makes that local root owned, and the next pass takes the
row as before.

The refcounts end the same: before, +1 per box field, −1 on the node, then −1 per field;
after, −1 on the node.

On the repro (v2.0.38, with fix 1), B went from 1116-1244 ms to 173-200 ms.

**Open question: lend instead of hand over at a tail call (cause 2)**

A callee whose body never needs its parameter owned could stay borrowed. The caller would
then make the call non-tail and drop its reference after the call returns. This costs a
frame per converted call, and the tail call is lost. Is that an acceptable trade, or is
there a better place to break cause 2?

**Tests**

The 2.0.38 prototype of fix 1 gave per-test results identical to the unpatched compiler on tests/rfc, tests/reg and tests/run (a local runner for the C lane: emit C, clang -O3, run on 4 threads, compare with the `#|` lines; 213 pass under both). The tests whose emitted C changed also pass under `-DBEND_POISON`. The v2.0.40 port above has been run only on the repro so far; I will add its suite result in a comment.

**The file**

```python
import Base

# A read-only walk over a shared List of a wide record (80 words: 8 unboxed
# 9-word parts + 8 boxed lists). The same walker body runs in three shapes:
#   A  lent : the caller uses the list after the call       -> term_peek per row
#   B  owned: the list reaches the walker as an owned value -> ctr_take(.., 80, ..) per row
#   C  lent, but a helper the body calls returns a boxed field of the row
#      (that helper's parameter is owned, so the walker's is too)
# All three compute the same checksum.

type Part is Data:
  Part{p0: U32, p1: U32, p2: U32, p3: U32, p4: U32, p5: U32, p6: U32, p7: U32, p8: U32}

type Row is Data:
  Row{a: Part, b: Part, c: Part, d: Part, e: Part, f: Part, g: Part, h: Part,
      t0: List<&2, U32>, t1: List<&2, U32>, t2: List<&2, U32>, t3: List<&2, U32>,
      t4: List<&2, U32>, t5: List<&2, U32>, t6: List<&2, U32>, t7: List<&2, U32>}

def part(+i: U32) -> Part:
  Part{i, U32.add(i, 1), 2, 3, 4, 5, 6, 7, 8}

def mk(+i: U32) -> Row:
  Row{part(i), part(1), part(2), part(3), part(4), part(5), part(6), part(7),
      [i, 1], [2], [3], [4], [5], [6], [7], [8]}

def table(n: Nat, +i: U32) -> List<&2, Row>:
  match n:
    case 0n: []
    case 1n+k: mk(i) <> table(k, U32.add(i, 1))

def len(xs: List<&2, U32>, acc: U32) -> U32:
  match xs:
    case Nil{}: acc
    case Con{x, rest}: len(rest, U32.add(acc, 1))

# the same count for C: ownership is inferred per def, so if C shared `len`
# it would make `len`'s parameter owned, and A with it
def len_c(xs: List<&2, U32>, acc: U32) -> U32:
  match xs:
    case Nil{}: acc
    case Con{x, rest}: len_c(rest, U32.add(acc, 1))

def Part.p0(p: Part) -> U32:
  match p:
    case Part{p0, p1, p2, p3, p4, p5, p6, p7, p8}: p0

# reads in place: returns scalars only
def Row.key(r: Row) -> U32:
  match r:
    case Row{a, b, c, d, e, f, g, h, t0, t1, t2, t3, t4, t5, t6, t7}: U32.add(Part.p0(a), len(t0, 0))

# returns a boxed field: its parameter is owned
def Row.t0(r: Row) -> List<&2, U32>:
  match r:
    case Row{a, b, c, d, e, f, g, h, t0, t1, t2, t3, t4, t5, t6, t7}: t0

def Row.a(r: Row) -> Part:
  match r:
    case Row{a, b, c, d, e, f, g, h, t0, t1, t2, t3, t4, t5, t6, t7}: a

def Row.key_c(+r: Row) -> U32:
  U32.add(Part.p0(Row.a(r)), len_c(Row.t0(r), 0))

def keep(+v: U32, +xs: List<&2, Row>) -> U32:
  v

def same(xs: List<&2, Row>) -> List<&2, Row>:
  xs

# A: lent
def walk_a(xs: List<&2, Row>, acc: U32) -> U32:
  match xs:
    case Nil{}: acc
    case Con{r, rest}: walk_a(rest, U32.add(acc, Row.key(r)))

def run_a(+xs: List<&2, Row>) -> U32:
  keep(walk_a(xs, 0), xs)

# B: the same body; the list arrives owned (a computed value in tail position)
def walk_b(xs: List<&2, Row>, acc: U32) -> U32:
  match xs:
    case Nil{}: acc
    case Con{r, rest}: walk_b(rest, U32.add(acc, Row.key(r)))

def run_b(+xs: List<&2, Row>) -> U32:
  walk_b(same(xs), 0)

# C: lent like A, but the body reads through Row.t0 (owned parameter)
def walk_c(xs: List<&2, Row>, acc: U32) -> U32:
  match xs:
    case Nil{}: acc
    case Con{r, rest}: walk_c(rest, U32.add(acc, Row.key_c(r)))

def run_c(+xs: List<&2, Row>) -> U32:
  keep(walk_c(xs, 0), xs)

def pk(b: Bool, +w: U32, +xs: List<&2, Row>) -> U32:
  match b:
    case True{}: run_b(xs)
    case False{}: run_c(xs)

def pick(b: Bool, +w: U32, +xs: List<&2, Row>) -> U32:
  match b:
    case True{}: run_a(xs)
    case False{}: pk(U32.is_eq(w, 1), w, xs)

def loop(n: Nat, +xs: List<&2, Row>, +w: U32, acc: U32) -> U32:
  match n:
    case 0n: acc
    case 1n+k:
      +v = pick(U32.is_eq(w, 0), w, xs)
      loop(k, xs, w, U32.add(acc, v))

def go(+xs: List<&2, Row>, +n: Nat) -> IO(Unit):
  do IO<Unit>:
    t0 : Nat <- IO.now()
    ra : U32 = loop(n, xs, 0, 0)
    +t1 : Nat <- IO.now()
    rb : U32 = loop(n, xs, 1, 0)
    +t2 : Nat <- IO.now()
    rc : U32 = loop(n, xs, 2, 0)
    t3 : Nat <- IO.now()
    IO.print("A lent  " ++ U32.show(ra) ++ " " ++ Nat.show(Nat.sub(t1, t0)) ++ " ms\nB owned " ++ U32.show(rb) ++ " " ++ Nat.show(Nat.sub(t2, t1)) ++ " ms\nC helper-owns " ++ U32.show(rc) ++ " " ++ Nat.show(Nat.sub(t3, t2)) ++ " ms")

def main() -> IO(Unit):
  go(table(256n, 0), 20000n)
